#!/usr/bin/env python3
"""Render the source-backed pilot report from an independently validated run."""
import argparse
from datetime import date
import gzip
import hashlib
import html
import json
import os
from pathlib import Path
os.environ.setdefault('MPLCONFIGDIR','/tmp/spmo-matplotlib')
os.environ.setdefault('XDG_CACHE_HOME','/tmp/spmo-render-cache')
Path(os.environ['XDG_CACHE_HOME']).mkdir(parents=True,exist_ok=True)
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.dates as mdates
from matplotlib.ticker import PercentFormatter, ScalarFormatter

ROOT=Path(__file__).resolve().parents[1]
COLORS={'M12-5bps':'#426e5d','S12-03-09-5bps':'#172c35','SPY-5bps':'#a8844f'}
LABELS={'M12-5bps':'Monthly · M12','S12-03-09-5bps':'March / September · S12','SPY-5bps':'SPY buy and hold'}

def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--run-dir',required=True,type=Path);args=p.parse_args()
 summary_path=ROOT/'site/data/etf-pilot-summary.json';s=json.loads(summary_path.read_text())
 validation=json.loads((ROOT/'site/data/etf-pilot-validation.json').read_text())
 assert validation['passed'] and validation['summary_sha256']==hashlib.sha256(summary_path.read_bytes()).hexdigest()
 assets=ROOT/'site/assets';assets.mkdir(exist_ok=True)
 plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False,'axes.facecolor':'#f6f4ed','figure.facecolor':'#f6f4ed','axes.labelcolor':'#172c35','text.color':'#172c35','xtick.color':'#57656a','ytick.color':'#57656a','savefig.bbox':'tight'})
 fig,(ax,dd)=plt.subplots(2,1,figsize=(11.5,7.5),sharex=True,gridspec_kw={'height_ratios':[2,1]})
 start=s['boundaries']['report_anchor_on_or_before'];finish=s['boundaries']['full_year_end_on_or_before']
 for identity,color in COLORS.items():
  r=json.loads(gzip.decompress((args.run_dir/(identity+'.json.gz')).read_bytes()))
  rows=[x for x in r['daily'] if start<=x['session']<=finish];anchor=rows[0]['nav'];peak=anchor
  dates=[date.fromisoformat(x['session']) for x in rows];wealth=[x['nav']/anchor for x in rows];declines=[]
  for x in rows:peak=max(peak,x['nav']);declines.append(x['nav']/peak-1)
  ax.plot(dates,wealth,color=color,label=LABELS[identity],lw=1.6)
  dd.plot(dates,declines,color=color,lw=1.15)
 ax.set_yscale('log');ax.set_ylabel('Growth of $1 · log scale');ax.yaxis.set_major_formatter(ScalarFormatter());ax.legend(frameon=False,loc='upper left');ax.grid(alpha=.2)
 ax.set_title('A shallower decline did not produce the highest ending wealth',loc='left',fontweight='bold',pad=17)
 dd.yaxis.set_major_formatter(PercentFormatter(1));dd.set_ylabel('Drawdown');dd.grid(alpha=.2);dd.xaxis.set_major_locator(mdates.YearLocator(5));dd.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
 fig.text(.125,.012,'2001–2025 · 5 bps per side · daily closes · each account normalized at the 2000 year-end anchor',fontsize=9,color='#57656a')
 fig.savefig(assets/'pilot-wealth-drawdown.svg');plt.close(fig)
 annual=sorted(s['primary_annual'],key=lambda x:x['year']);fig,ax=plt.subplots(figsize=(11.5,4.3))
 years=[x['year'] for x in annual];values=[x['net_return_difference_pp'] for x in annual]
 ax.bar(years,values,color=['#426e5d' if v>0 else '#ba5e34' for v in values],width=.72);ax.axhline(0,color='#172c35',lw=.8)
 ax.set_ylabel('Monthly − semiannual return · pp');ax.set_title('The frequency effect changes from year to year',loc='left',fontweight='bold',pad=15);ax.set_xticks(years[::2]);ax.grid(axis='y',alpha=.2);ax.set_axisbelow(True)
 fig.text(.125,.01,'Primary 12–1 signal · March/September control · 5 bps per side · all 25 complete years shown',fontsize=9,color='#57656a');fig.savefig(assets/'pilot-annual-spread.svg');plt.close(fig)
 phases=['Jan / Jul','Feb / Aug','Mar / Sep','Apr / Oct','May / Nov','Jun / Dec'];fig,axes=plt.subplots(1,2,figsize=(11.5,4.5),sharey=True)
 for ax,signal,title in zip(axes,['12-1','mixed'],['Primary 12–1 signal','Blended signal · robustness']):
  for cost,color in zip([0,5,10,25],['#a8844f','#426e5d','#63879b','#ba5e34']):
   rows=[r for r in s['comparisons']['full_period'] if r['signal']==signal and r['cost_bps_per_side']==cost]
   ax.plot(range(6),[r['cagr_difference_pp'] for r in rows],marker='o',label=f'{cost} bps',color=color,lw=1.1,ms=4)
  ax.axhline(0,color='#172c35',lw=.8);ax.axvspan(1.75,2.25,color='#d5d9cf',alpha=.55);ax.set_xticks(range(6),phases,rotation=35,ha='right');ax.set_title(title,loc='left',fontweight='bold');ax.grid(axis='y',alpha=.2)
 axes[0].set_ylabel('Monthly − semiannual CAGR · pp / year');axes[1].legend(frameon=False,ncol=2)
 fig.text(.125,.01,'All six phases and four cost scenarios · shaded phase is the fixed March/September reference',fontsize=9,color='#57656a');fig.savefig(assets/'pilot-calendar-costs.svg');plt.close(fig)
 # Canonicalize publication-only whitespace; private run artifacts remain immutable.
 for figure in assets.glob('pilot-*.svg'):
  figure.write_text('\n'.join(line.rstrip() for line in figure.read_text().splitlines())+'\n')
 for table in (ROOT/'site/data').glob('etf-pilot-*.csv'):
  table.write_bytes(table.read_bytes().replace(b'\r\n',b'\n'))
 byid={r['run_id']:r for r in s['runs']};primary=s['primary']['full_period'];ytd=s['primary']['ytd2026'];rows=''
 pct=lambda x:f'{100*x:,.2f}%';pp=lambda x:f'{x:+.2f} pp'
 for identity in ['M12-5bps','S12-03-09-5bps','MMIX-5bps','SMIX-03-09-5bps','SPY-5bps']:
  r=byid[identity];m=r['metrics']['full_period'];rows+=f"<tr><th scope='row'>{html.escape(identity.replace('-5bps',''))}</th><td>{pct(m['cagr'])}</td><td>{pct(m['total_return'])}</td><td>{pct(m['max_drawdown'])}</td><td>{m['annualized_two_sided_turnover']:.2f}×</td><td>{pct(m['mean_cash_weight'])}</td></tr>"
 wins=sum(x['net_return_difference_pp']>0 for x in annual)
 direction='lower' if primary['cagr_difference_pp']<0 else 'higher'
 headline=f"Monthly Rebalancing: {abs(primary['cagr_difference_pp']):.2f} pp {direction.capitalize()} CAGR"
 body=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Sector ETF momentum results comparing rebalancing frequencies, calendar phases, and trading costs, with methods and limitations."><title>Sector ETF Momentum: Rebalancing Frequency and Cost Sensitivity · Rebalance Lab</title><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="pilot.css"><script src="pilot.js" defer></script></head><body class="pilot-page"><a class="skip-link" href="#main">Skip to content</a><header class="site-header wrap"><a class="brand" href="index.html">Rebalance <strong>Lab</strong></a><nav class="pilot-nav" aria-label="Report navigation"><a href="index.html">Overview</a><a href="stocks.html">Stock study</a><a href="#methods">Method &amp; limits</a><a href="https://github.com/Yuchi-Wang02/rebalance-lab/blob/main/docs/studies/sector-etf-pilot.md">Read the retrospective</a></nav></header><main id="main" class="wrap pilot-main"><section class="pilot-hero"><p class="eyebrow">Study 02 · sector ETFs · 2001–2025</p><h1>{headline}</h1><p class="pilot-lead">In the fixed 2001–2025 comparison, the monthly 12–1 portfolio grew at <strong>{pct(primary['monthly_cagr'])}</strong> a year versus <strong>{pct(primary['semiannual_cagr'])}</strong> for March/September selection. Monthly trading had a shallower maximum drawdown, and required substantially more trading.</p><p class="scope-box"><strong>What this answers:</strong> selection frequency in a nine-sector-ETF, three-slot strategy under an adjusted-price model. <strong>What it does not answer:</strong> the original 75-stock, historical-capitalization-weighted SPMO-inspired experiment. That study remains blocked by documented data gaps.</p></section><section class="pilot-facts" aria-label="Primary comparison at 5 basis points"><div><span>CAGR difference</span><strong>{pp(primary['cagr_difference_pp'])}</strong><small>Monthly minus March/September</small></div><div><span>Maximum drawdown</span><strong>{pct(primary['monthly_max_drawdown'])}</strong><small>Monthly; semiannual {pct(primary['semiannual_max_drawdown'])}</small></div><div><span>Annual traded notional</span><strong>{byid['M12-5bps']['metrics']['full_period']['annualized_two_sided_turnover']:.2f}×</strong><small>Monthly; semiannual {byid['S12-03-09-5bps']['metrics']['full_period']['annualized_two_sided_turnover']:.2f}× NAV</small></div><div><span>Positive calendar years</span><strong>{wins} / 25</strong><small>A count, not an independence test</small></div></section><figure><img src="assets/pilot-wealth-drawdown.svg" alt="Normalized daily wealth and drawdown for monthly, March September, and SPY portfolios from 2001 through 2025."><figcaption>Primary signal at 5 bps per side. Daily data; log wealth scale. Holdings continue through every year-end. SPY is product context, not a frequency control.</figcaption></figure><section><h2>Return, Risk and Trading Activity</h2><div class="table-scroll" tabindex="0" role="region" aria-label="Full-period performance"><table><caption>2001–2025 · all figures net of modeled trading costs at 5 bps per side</caption><thead><tr><th>Portfolio</th><th>CAGR</th><th>Total return</th><th>Max drawdown</th><th>Traded NAV / year</th><th>Mean cash</th></tr></thead><tbody>{rows}</tbody></table></div><p>Traded NAV counts buys plus sells, without dividing by two. Cash earns zero interest. Drawdowns use daily closes. These are retrospective modeled results, not achievable execution records or forecasts.</p></section><figure><img src="assets/pilot-annual-spread.svg" alt="All 25 annual monthly-minus-semiannual return differences, with positive and negative years shown."><figcaption>The monthly portfolio leads in {wins} of 25 individual years; compounded growth still favors the fixed semiannual control. Annual differences are not independent experiments.</figcaption></figure><section><h2>Calendar-Phase and Cost Sensitivity</h2><p>March/September remains primary. The other five schedules are sensitivity checks, not candidates from which we choose a winner. Every cost level is a separately simulated account.</p><figure><img src="assets/pilot-calendar-costs.svg" alt="CAGR differences across all six semiannual phases and four trading-cost scenarios, for both prespecified signals."><figcaption>Above zero favors monthly selection. Lines connect discrete tested scenarios; no untested cost crossover is estimated.</figcaption></figure><div class="pilot-controls"><label>Signal <select id="pilot-signal"><option value="12-1">12–1 · primary</option><option value="mixed">Blended · robustness</option></select></label><label>Cost per side <select id="pilot-cost"><option value="0">0 bps</option><option value="5" selected>5 bps</option><option value="10">10 bps</option><option value="25">25 bps</option></select></label></div><div class="table-scroll" tabindex="0" role="region" aria-label="All phase comparisons"><table><caption id="phase-caption">Six semiannual phases · 12–1 signal · 5 bps</caption><thead><tr><th>Phase</th><th>Monthly CAGR</th><th>Semiannual CAGR</th><th>Difference</th><th>Drawdown difference</th></tr></thead><tbody id="phase-rows"></tbody></table></div><p id="pilot-data-status" role="status">Loading the saved comparison table…</p></section><section class="case-study"><p class="eyebrow">Secondary case · 2026 through October 2</p><h2>2026 Year-to-Date Comparison</h2><p>The monthly primary portfolio returned <strong>{pct(ytd['monthly_total_return'])}</strong>, versus <strong>{pct(ytd['semiannual_total_return'])}</strong> for March/September: a <strong>{pp(ytd['net_return_difference_pp'])}</strong> difference. This partial year is not annualized, and it does not replace the prespecified 25-year comparison. The blended signal has a different outcome; inspect the complete tables.</p></section><section id="methods"><h2>Methods, Verification and Limitations</h2><div class="method-grid"><article><h3>Validation Within the Pilot Scope</h3><p>Nine sector ETFs plus SPY; {s['audit']['common_session_count']:,} common sessions from December 22, 1998 through October 2, 2026. The calendar, missing values, input hashes, signal timing, fees and independent accounting replay were checked.</p></article><article><h3>Adjusted-Price Accounting</h3><p>Signals use vendor adjusted closes. Trades use Open × AdjClose / Close. These are total-return proxy units; no separate dividend cash is added. This does not reproduce actual dividend payment dates or raw-share execution.</p></article><article><h3>Restricted ETF Universe</h3><p>Three equal-sized slots among the original nine sector ETFs, with empty slots held as cash. Sector definitions changed over time. This is neither the top-75 stock strategy nor a replication of the official SPMO index.</p></article><article><h3>Retrospective Evidence</h3><p>The design was frozen before this execution, after the history was already observable. All phases and costs are published. There is no untouched holdout, statistical significance claim, tax model or validated trading capacity.</p></article></div><details><summary>Sources, Run Artifacts and Verification</summary><ul><li><a href="https://github.com/Yuchi-Wang02/rebalance-lab/blob/main/docs/methods/sector-etf-protocol.md">Frozen pilot protocol and formulas</a></li><li><a href="data/etf-pilot-summary.json">Saved derived results and source-response hashes</a></li><li><a href="data/etf-pilot-validation.json">Independent accounting verification</a></li><li><a href="data/etf-pilot-full_period.csv">Every full-period paired comparison · CSV</a></li><li><a href="data/etf-pilot-annual.csv">All annual paired comparisons · CSV</a></li><li><a href="data/etf-pilot-ytd2026.csv">All 2026 YTD paired comparisons · CSV</a></li><li><a href="https://github.com/Yuchi-Wang02/rebalance-lab/blob/main/docs/data/original-data-audit.md">Why the original stock experiment is still incomplete</a></li></ul><p class="run-id">Run {html.escape(s['run_id'])} · configuration SHA-256 {s['config_sha256']}</p></details></section><section class="takeaway"><h2>Interpretation</h2><p>Faster updating is not a free improvement. In the primary long-period comparison it bought a shallower drawdown, but lower compounded growth and more turnover. The sign changes across calendar choices. The strong 2026 primary result therefore supports further investigation, not a broad claim that monthly momentum wins.</p><a class="button button-dark" href="https://github.com/Yuchi-Wang02/rebalance-lab/blob/main/docs/studies/sector-etf-pilot.md">Read the complete retrospective</a></section></main><footer class="wrap pilot-footer">Rebalance Lab · Independent research. Modeled history, not a forecast or investment advice. Raw vendor observations remain private; these files publish derived results and audit metadata.</footer></body></html>'''
 (ROOT/'site/pilot.html').write_text(body)
 print(json.dumps({'rendered':True,'run_id':s['run_id'],'figures':3,'primary_cagr_difference_pp':primary['cagr_difference_pp']}))

if __name__=='__main__':main()
